let raw = $json.output;

let analysis;

try {
  if (typeof raw === 'string') {
    raw = raw
      .replace(/^```json\s*/i, '')
      .replace(/^```\s*/i, '')
      .replace(/\s*```$/i, '')
      .trim();

    analysis = JSON.parse(raw);
  } else {
    analysis = raw;
  }
} catch (error) {
  throw new Error("AI returned invalid JSON: " + raw);
}

const article = $('Remove Duplicates').item.json;

return {
  json: {
    title: article.title,
    link: article.link,
    pubDate: article.pubDate || article.isoDate,

    category: analysis.category || "Other",
    importance_score: Number(analysis.importance_score) || 0,
    market_impact: analysis.market_impact || "Unclear",
    key_points: analysis.key_points || [],
    summary: analysis.summary || "",
    investor_relevance: analysis.investor_relevance || "",
    content_potential: analysis.content_potential || "Low",
    content_angle: analysis.content_angle || ""
  }
};

const articleTitle = $('Filter1').item.json.title || "";
const results = Array.isArray($json.results) ? $json.results : [];

if (results.length === 0) {
  return [{
    json: {
      platform: "LinkedIn",
      article_title: articleTitle,
      title: "",
      url: "",
      content: "",
      published_date: "",
      available: false
    }
  }];
}

return results.map(item => ({
  json: {
    platform: "LinkedIn",
    article_title: articleTitle,
    title: item.title || "",
    url: item.url || "",
    content: item.content || "",
    published_date: item.published_date || "",
    available: true
  }
}));

const articleTitle = $('Filter1').item.json.title || "";
const results = Array.isArray($json.results) ? $json.results : [];

if (results.length === 0) {
  return [{
    json: {
      platform: "X",
      article_title: articleTitle,
      title: "",
      url: "",
      content: "",
      published_date: "",
      available: false
    }
  }];
}

return results.map(item => ({
  json: {
    platform: "X",
    article_title: articleTitle,
    title: item.title || "",
    url: item.url || "",
    content: item.content || "",
    published_date: item.published_date || "",
    available: true
  }
}));

const items = $input.all();

const grouped = {};

for (const item of items) {
  const articleTitle = item.json.article_title || "Unknown Article";

  if (!grouped[articleTitle]) {
    grouped[articleTitle] = [];
  }

  if (item.json.available === false) {
    continue;
  }

  grouped[articleTitle].push({
    platform: item.json.platform || "",
    title: item.json.title || "",
    content: item.json.content || "",
    url: item.json.url || "",
    published_date: item.json.published_date || ""
  });
}

return Object.entries(grouped).map(([articleTitle, posts]) => ({
  json: {
    article_title: articleTitle,
    social_intelligence: posts
  }
}));
